const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry: 300-meter radius around the point
  const point = ee.Geometry.Point([34.770153, -118.423217]);
  const geometry = point.buffer(300);

  // 2. Get Landsat 8 data for April 14, 2020
  let col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate('2020-04-14', '2020-04-15')
    .filterBounds(geometry);

  let size = col.size().getInfo();
  console.log(`Landsat 8 Images found: ${size}`);

  if (size === 0) {
    console.log('No Landsat 8 data for April 14, 2020.');
    console.log('C1');
    return;
  }

  // 3. Get first image and apply cloud masking
  let img = ee.Image(col.first());

  // Cloud masking for Landsat 8 C2 (using QA_PIXEL band)
  let qaMask = img.select('QA_PIXEL').bitwiseAnd(32).eq(0); // Cloud bit
  let imgMasked = img.updateMask(qaMask);

  // 4. Calculate NDVI: (NIR - Red) / (NIR + Red)
  // Landsat 8 bands: B5 = NIR, B4 = Red
  let ndvi = imgMasked.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');

  // 5. Calculate mean NDVI and NIR reflectance in the area
  let ndviStats = ndvi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  });

  let nirStats = imgMasked.select('SR_B5').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  });

  let redStats = imgMasked.select('SR_B4').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  });

  // Count valid pixels
  let pixelCount = ndvi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  });

  let ndviValue = ndviStats.get('NDVI').getInfo();
  let nirValue = nirStats.get('SR_B5').getInfo();
  let redValue = redStats.get('SR_B4').getInfo();
  let validPixels = pixelCount.get('NDVI').getInfo();

  console.log(`Valid Pixels: ${validPixels}`);
  console.log(`Mean NDVI: ${(ndviValue !== null ? ndviValue.toFixed(4) : 'null')}`);
  console.log(`Mean NIR (B5): ${(nirValue !== null ? nirValue.toFixed(0) : 'null')}`);
  console.log(`Mean Red (B4): ${(redValue !== null ? redValue.toFixed(0) : 'null')}`);

  // 6. Handle no valid pixels
  if (validPixels === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('C2');
    return;
  }

  // 7. Validation: Check for null or invalid results
  if (ndviValue === null || isNaN(ndviValue) || nirValue === null || redValue === null) {
    console.log('Calculation resulted in invalid values.');
    console.log('C3');
    return;
  }

  // 8. Decision Logic:
  // Water: NDVI < 0 (usually negative), low NIR reflectance
  // Solar Farm: NDVI between 0.1-0.4, moderate-high NIR, moderate Red

  console.log(`NDVI Analysis:`);
  if (ndviValue < -0.1) {
    console.log('Strong negative NDVI indicates water body.');
    console.log('B');
  } else if (ndviValue >= -0.1 && ndviValue <= 0.3 && nirValue > 500) {
    console.log('Moderate NDVI with elevated NIR suggests solar farm.');
    console.log('A');
  } else if (ndviValue > 0.3) {
    console.log('High NDVI indicates vegetation, not solar farm or water.');
    console.log('B');
  } else {
    console.log('Inconclusive spectral signature.');
    console.log('C3');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
